// Generated by warp.py: output frame -> source frame, piecewise linear (source = the original 48 s cut).
export const WARP: [number, number][] = [[0, 0], [112, 112], [172, 172], [224, 221], [252, 248], [256, 252], [294, 309], [296, 312], [336, 412], [364, 460], [366, 463], [392, 492], [434, 577], [436, 581], [462, 647], [486, 723], [506, 745], [508, 752], [532, 777], [534, 779], [588, 914], [590, 919], [630, 1013], [654, 1033], [710, 1080], [730, 1102], [732, 1104], [756, 1128], [758, 1130], [826, 1235], [828, 1238], [896, 1330], [898, 1333], [930, 1415], [956, 1452], [974, 1472], [978, 1478], [1004, 1667], [1013, 1694], [1078, 1882], [1080, 1887], [1148, 2103], [1162, 2123], [1164, 2126], [1204, 2178], [1206, 2181], [1252, 2295], [1260, 2312], [1262, 2316], [1280, 2338], [1304, 2365], [1376, 2437], [1440, 2501]];
export const OUT_DURATION = 2501;
export const srcAt = (fo: number) => {
  for (let i = 1; i < WARP.length; i++) {
    const [s0, o0] = WARP[i - 1];
    const [s1, o1] = WARP[i];
    if (fo < o1 || i === WARP.length - 1) return s0 + ((fo - o0) * (s1 - s0)) / (o1 - o0);
  }
  return fo;
};
// source frames per output frame (1 = original speed)
export const rateAt = (fo: number) => {
  for (let i = 1; i < WARP.length; i++) if (fo < WARP[i][1] || i === WARP.length - 1) return (WARP[i][0] - WARP[i - 1][0]) / (WARP[i][1] - WARP[i - 1][1]);
  return 1;
};
// output frame of a source frame
export const outAt = (fs: number) => {
  for (let i = 1; i < WARP.length; i++) {
    const [s0, o0] = WARP[i - 1];
    const [s1, o1] = WARP[i];
    if (fs < s1 || i === WARP.length - 1) return o0 + ((fs - s0) * (o1 - o0)) / (s1 - s0);
  }
  return fs;
};
